seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
comp=str.maketrans('ACGT','TGCA')
stops={'TAA','TAG','TGA'}
def stopfree_run(s,start):
    n=0;i=start
    while i+3<=len(s) and s[i:i+3] not in stops:
        n+=1;i+=3
    return n
def prev_stop(s,p,f):
    # previous stop codon in same frame f (positions = f mod 3), before p
    q=p-3
    while q>=f:
        if s[q:q+3] in stops: return q
        q-=3
    return None

def scan(s,label):
    print('====',label)
    for p in range(len(s)-2):
        if s[p:p+3] in stops:
            f=p%3
            n1=stopfree_run(s,p+1)   # +1 shift frame (f+1)
            n2=stopfree_run(s,p+2)   # -1 shift frame (f+2)
            ps=prev_stop(s,p,f)
            up_len = 0 if ps is None else (p-ps)//3 - 1
            atg_up=[]
            start=0 if ps is None else ps+3
            for q in range(start,p,3):
                if s[q:q+3]=='ATG': atg_up.append(q)
            best=max(n1,n2)
            if best>=120:
                print(f'stop@ {p} {s[p:p+3]} frame{f}: up-frame ORF_len={up_len} (prev stop {ps}) ATGs_up={atg_up[:6]} | +1run={n1} -1run={n2}')

scan(seq,'plus')
